import fs from 'node:fs';
const units=[JSON.parse(fs.readFileSync(new URL('./unit-one.json',import.meta.url),'utf8'))];
let active;function unit(title,description){active={id:units.length+1,title,description,lessons:[]};units.push(active)}
function topic(title,intro,workflow,text,activity){const rows=text.trim().split('\n').map(l=>l.split('|'));if(rows.length!==5||rows.some(r=>r.length!==4))throw Error(title+' needs five complete teaching rows');const id=`u${active.id}-l${active.lessons.length+1}`;let questions=rows.map(([term,prompt,right,wrong],j)=>{const wrongs=[wrong,...rows.filter((_,k)=>k!==j).slice(0,2).map(r=>r[3])];let opts=[right,...wrongs];const rotate=(active.id+j)%4;opts=[...opts.slice(rotate),...opts.slice(0,rotate)];return{type:'choice',prompt,options:opts,answer:opts.indexOf(right),explanation:`${right}. ${term} is the focus of this decision.`}});questions.push(...rows.slice(0,3).map(([term,,right,wrong],j)=>{let opts=[right,...[wrong,...rows.filter((_,k)=>k!==j).slice(-2).map(r=>r[3])]];const rotate=(j+2)%4;opts=[...opts.slice(rotate),...opts.slice(0,rotate)];return{type:'choice',prompt:`A teammate writes: “${wrong}.” Which revision best corrects this claim about ${term.toLowerCase()}?`,options:opts,answer:opts.indexOf(right),explanation:`Replace the misconception with this principle: ${right}.`}}));questions.splice(3,0,{type:'match',prompt:`Connect the concepts in “${title}” to their meaning.`,pairs:rows.slice(0,3).map(r=>[r[0],r[2]]),explanation:rows.slice(0,3).map(r=>`${r[0]}: ${r[2]}.`).join(' ')});questions.push({type:'order',prompt:`Arrange this practical workflow for ${title.toLowerCase()}.`,items:workflow.split(' > '),explanation:`Follow this workflow: ${workflow.replaceAll(' > ',' → ')}. Review the outcome before using it.`});questions=questions.map((q,j)=>({...q,id:`${id}-q${j+1}`}));active.lessons.push({id,unit:active.id,title,sub:intro,icon:['✦','◎','▥','✧','⌘','◇'][active.lessons.length],concept:intro,sections:rows.map(r=>({title:r[0],text:r[2]+'.',example:r[1],pitfall:r[3]})),tip:'Check the requirement, identify the relevant principle, and explain why the alternatives fall short.',activity:activity||`Apply the workflow to one example from school, work or everyday life. Write your decision, supporting evidence and one remaining limitation.`,questions});}
unit('How AI Learns','Understand data, learning methods and reliable evaluation.');
topic('Data, features and labels','A model learns from representations of examples. Features describe inputs; labels supply known answers in supervised learning.',['Define the prediction target','Collect suitable features and labels','Check quality and split the data'].join(' > '),`
Features|You predict bus journey duration. Which input is most defensible before departure?|Use available route, departure time and current traffic features|Use the actual arrival time as an input available before departure
Labels|A supervised model predicts house prices. What should each training label represent?|Use a reliable observed sale price for the corresponding house|Use the model’s own unverified guess as every ground-truth price
Missing values|A sensor has blanks that sometimes mean device failure. What should you do first?|Investigate why values are missing before choosing an imputation strategy|Replace every blank with zero without checking its meaning
Representation|Customer ID numbers appear strongly related to purchase outcomes in a small sample. What is prudent?|Check whether IDs carry relevant generalisable information or an accidental pattern|Treat any numerical ID as a meaningful measure of customer behaviour
Data quality|Two records use kilometres and miles in the same distance column. What is needed?|Standardise units and verify the corrected records before training|Let the model infer all unit conversions from the mixed values`);
topic('Supervised learning','Learn from examples with known targets. Classification predicts categories; regression predicts numerical values.','Define the target and task type > Train using labelled examples > Evaluate predictions on separate data',`
Classification|A school sorts feedback into positive, neutral and negative. Which setup fits?|Train a classifier using feedback with reliable category labels|Treat sentiment categories as continuous measured distances
Regression|A shop predicts tomorrow’s revenue as a rupee amount. Which setup fits?|Use regression with past examples and relevant available features|Use revenue amounts as arbitrary class names with no numerical relationship
Label consistency|Two annotators assign conflicting complaint categories. What should happen?|Clarify the labelling guide and review disagreement before relying on labels|Assume disagreements are harmless because the dataset is large
Baseline|A complex predictor is being proposed. What is a useful first comparison?|Compare it with a simple relevant baseline on the same evaluation data|Compare the new model’s training score with a competitor’s advertisement
Prediction time|A model predicts whether a customer will cancel next month. Which feature is inappropriate?|Exclude information recorded only after the cancellation outcome|Include the final cancellation reason as if known when predicting`);
topic('Unsupervised learning','Discover structure without supplied target labels. Clusters and anomalies depend on representation, settings and context.','Choose relevant features and scaling > Explore clusters or unusual examples > Validate usefulness with domain knowledge',`
Clustering|A shop wants to explore customer groups without existing group labels. What fits?|Cluster customers using suitable behaviour features and inspect the groups|Declare the groups to be verified personality types
Scaling|Spending ranges into lakhs while visit counts range from one to ten. What needs attention?|Consider appropriate scaling so large numerical units do not dominate distance|Assume every distance method automatically ignores measurement units
Cluster interpretation|An algorithm finds three clusters. What can be concluded?|Three groups were found under these features and settings; usefulness needs checking|There are exactly three natural customer types in every market
Anomaly detection|A transaction is flagged as unusual. What is justified?|Investigate the transaction because unusual does not automatically mean fraudulent|Reject it as proven fraud without further evidence
Evaluation|No ground-truth group labels exist. How can you assess usefulness?|Combine appropriate structural measures with domain review and task outcomes|Use classification accuracy against labels that were never supplied`);
topic('Reinforcement learning','An agent acts in an environment and receives reward signals. Reward design and safe exploration shape behaviour.','Define environment, actions and constraints > Choose rewards and train safely > Evaluate behaviour beyond the reward score',`
Reward|A game agent receives points after useful moves. What does the reward represent?|A feedback signal used to learn behaviour toward an objective|A guarantee that the objective captures every desirable behaviour
Exploration|A simulator allows a robot agent to try new strategies. What is exploration?|Trying actions to gather information about their consequences|Always repeating the currently highest-rated action without trying alternatives
Reward hacking|An agent maximises clicks by showing misleading headlines. What went wrong?|The rewarded metric did not fully represent the intended quality objective|The agent necessarily developed human intentions to deceive
Safety constraints|An agent could learn by experimenting with real machinery. What is prudent?|Use controlled evaluation and appropriate constraints before real-world actions|Allow unrestricted real-world experimentation because rewards will correct mistakes
Delayed reward|A useful action helps the agent win many steps later. What is challenging?|Attributing later outcomes to earlier actions can be difficult|Only immediately rewarded actions can ever be learned`);
topic('Training, validation and testing','Use separate data roles to develop and evaluate a model. Keep the final test set independent of routine model selection.','Split data with leakage controls > Train and tune using training and validation data > Evaluate the final choice on held-out test data',`
Training set|Which data should directly fit model parameters?|Use training examples to adjust the model during learning|Tune parameters repeatedly using the final test answers
Validation set|You compare model settings during development. Which data role fits?|Use validation data for model selection and tuning|Use deployment users as an uncontrolled substitute for validation
Test set|A team repeatedly chooses settings based on its final test score. What is the concern?|The test set has become part of model selection and may overstate generalisation|Repeated testing makes the final score automatically more independent
Time split|You predict next week’s demand using historical sales. What split is often more realistic?|Train on earlier periods and evaluate on later periods without future information|Shuffle future records into the past so all dates influence every example
Duplicates|Near-identical photos appear in both training and test sets. What should you check?|Group related examples appropriately to reduce leakage across splits|Keep duplicates because they guarantee more reliable independent testing`);
topic('Metrics, overfitting and changing data','Choose metrics that reflect the actual problem. A single high score can hide important failures or changing conditions.','Identify consequential errors > Evaluate suitable metrics and slices > Monitor performance as conditions change',`
Precision|A spam filter should minimise blocking legitimate mail. Which metric is relevant?|Inspect precision among flagged spam and the legitimate messages wrongly flagged|Optimise only total message volume without examining mistakes
Recall|A safety screening tool must identify most relevant cases. What needs attention?|Measure recall of actual relevant cases while also reviewing false alarms|Treat precision alone as proof that almost all relevant cases were found
Overfitting|Training accuracy rises while validation performance worsens. What is plausible?|The model may be fitting training-specific noise rather than generalisable patterns|Better training accuracy guarantees better unseen performance
Class imbalance|A model labels all 1000 cases negative when only 10 are positive. What does 99% accuracy hide?|It misses every positive case despite high overall accuracy|It successfully detects ninety-nine percent of the positive cases
Data drift|A bus predictor degrades after route changes. What should you do?|Monitor relevant new data, investigate drift and re-evaluate before updating|Assume an old test score guarantees performance after the environment changes`);
unit('Inside Modern AI','Explore neural networks, language models and the limits of their representations.');
topic('Neural networks and deep learning','Neural networks combine adjustable numerical operations. Layers learn representations; their similarity to brains is limited.','Choose an architecture suited to the task > Fit weights using training data > Evaluate generalisation and failure cases',`
Weights|What changes when a neural network learns from examples?|Numerical parameters are adjusted to reduce a training objective|A miniature human brain is created inside each processing unit
Layers|Why use multiple layers in a network?|Layers can compose increasingly useful representations for a task|Each additional layer guarantees factual accuracy
Activation|Why include nonlinear activation functions?|Nonlinearity allows a network to represent more than a single linear mapping|An activation function directly supplies verified human reasoning
Deep learning|How does deep learning relate to machine learning?|It uses neural networks with multiple processing layers as one family of methods|It is a separate field that never uses data-driven learning
Capacity|A larger network is proposed for a small dataset. What should be considered?|Capacity, data quality, resources and evaluation matter together|More parameters always eliminate overfitting and data problems`);
topic('Loss and optimisation','A loss quantifies training error according to a chosen objective. Optimisation adjusts parameters; reducing loss is not the same as meeting every real-world need.','Define an appropriate loss > Update parameters using an optimisation method > Check validation behaviour and task outcomes',`
Loss function|Why choose a loss function during training?|It gives a numerical objective measuring a chosen kind of prediction error|It measures all social and practical consequences automatically
Gradient descent|What does a gradient-based update try to do?|Adjust parameters in a direction intended to reduce the training loss|Search every possible model and prove the global optimum
Learning rate|Training updates repeatedly overshoot and become unstable. What might help?|Investigate the learning rate and other training conditions|Increase update size indefinitely to force faster convergence
Epoch|What does one training epoch usually mean?|One pass over the training dataset under the training procedure|One guaranteed percentage-point improvement in accuracy
Real-world performance|Training loss decreases. What should you conclude?|The training objective improved; independent task evaluation is still needed|All future outputs and downstream decisions are now reliable`);
topic('Language models, tokens and context','Language models process token sequences. Context is the information available for a request, not unlimited permanent memory.','Provide relevant instructions and context > Generate within the model’s limits > Check the response against evidence and requirements',`
Tokens|A sentence is split into tokens. Which description is accurate?|Tokens can be words, word parts or other text units depending on the tokenizer|Every token corresponds to exactly one complete English word
Context window|A very long conversation loses earlier details. What is a useful explanation?|Only a bounded amount of information can be available in the current context|All previous conversations are necessarily stored in every model request
Generation|How does a language model produce text at a basic level?|It predicts successive tokens conditioned on its available context|It always retrieves an exact verified sentence from a live encyclopedia
Memory|You tell a chatbot your preference once. What should you assume?|Persistence depends on the product; do not assume every later session retains it|Every model permanently retrains itself on that message immediately
Truncation|A long report exceeds a tool’s context limit. What is prudent?|Select or retrieve relevant sections and verify coverage of the task|Assume unseen or truncated sections were fully considered`);
topic('Embeddings and semantic similarity','Embeddings represent inputs as numerical vectors. Distance can support similarity search but is not proof of truth, identity or intent.','Choose an embedding method for the inputs > Compare vectors using a suitable similarity measure > Evaluate retrieved matches for the task',`
Embedding|What is an embedding in a search system?|A numerical representation used to compare relevant aspects of inputs|A hidden digital certificate proving the input is true
Semantic search|A query and document use different wording but similar meaning. What can help?|Embedding-based retrieval can find semantic relationships beyond exact word overlap|Only identical spelling can ever connect two pieces of text
Similarity|Two documents have similar vectors. What follows?|They are similar under the chosen representation, not necessarily equally accurate|They contain identical verified facts in all contexts
Domain fit|A general embedding model struggles with specialist abbreviations. What is prudent?|Evaluate representation quality on domain examples and consider suitable alternatives|Assume vector distance has the same meaning in every technical domain
Sensitive vectors|Should embeddings of private records be treated as automatically anonymous?|No; protect them appropriately because representations can still carry sensitive information|Yes; conversion to numbers always removes every privacy risk`);
topic('Transformers and attention','Attention lets a transformer combine information from different positions. Contextual patterns can be powerful without guaranteeing understanding or correctness.','Represent the input tokens > Compute contextual relationships across tokens > Produce and evaluate the task output',`
Attention|In a sentence with an ambiguous pronoun, what can attention help a model use?|Relationships between relevant tokens in the available context|A direct reading of the author’s private intention
Transformer|Which statement describes a transformer appropriately?|An architecture using attention-based processing for sequence representations|A guarantee that generated statements have been independently verified
Position information|Why does token order matter?|Order helps distinguish meanings such as who acted on whom|A transformer must treat every possible token order as identical
Contextual meaning|The word bank appears beside river. What helps disambiguate it?|Surrounding context can influence the token’s representation|Each word must have one unchanging meaning in every sentence
Attention explanation|Can an attention pattern alone prove the model’s entire reasoning process?|No; interpreting model behaviour requires care beyond inspecting one attention map|Yes; every attention weight is a complete causal explanation`);
topic('Pretraining, fine-tuning and retrieval','Pretraining learns broad patterns; fine-tuning adapts model parameters; retrieval supplies relevant external material at request time.','Identify the capability or information gap > Choose prompting, retrieval or adaptation appropriately > Evaluate benefits, limits and maintenance needs',`
Pretraining|What does broad pretraining usually provide?|Patterns learned from a large training corpus for later tasks|Guaranteed knowledge of every future event and private document
Fine-tuning|A team trains an existing model on curated task examples. What changes?|Model parameters are adapted using those examples|Only a search index changes while all model parameters must remain fixed
Retrieval|A chatbot needs this week’s approved fee circular. Which approach is appropriate?|Retrieve the current authorised document and ground answers in it|Assume fine-tuning last year necessarily supplies this week’s fee changes
Method choice|A task only needs a clearer output format. What should you try first?|A precise instruction and examples before committing to retraining|Immediately train a new foundation model from scratch
Evaluation|A fine-tuned model sounds more on-brand. What remains necessary?|Check factuality, safety and task performance independently of tone|Treat consistent brand language as proof that all errors are fixed`);
unit('Generative AI','Create text, images, audio and video with careful review and traceable evidence.');
topic('Text generation and summarisation','Generated drafts are useful starting points. Faithful summaries preserve meaning, limitations and important qualifications from their source.','Define audience and supply source material > Generate a constrained draft > Verify claims, omissions and tone',`
Source fidelity|A report says results are preliminary but the summary calls them proven. What is needed?|Restore the uncertainty and verify that the summary preserves the source’s meaning|Keep the stronger claim because summaries should sound decisive
Missing information|An invitation draft lacks a venue. How should the model handle it?|Flag the missing venue or use a clearly marked placeholder|Invent a realistic local venue to make the draft complete
Attribution|A summary includes a quote that is not in the source. What should happen?|Remove or verify the quote against an authentic source before attributing it|Retain the quote if it fits the author’s likely opinion
Audience|A technical report must be explained to beginners. What is the goal?|Simplify language while preserving the underlying claims and limitations|Remove every qualification to make the conclusion more memorable
Editing|A draft is grammatically polished. Which review still matters?|Check evidence, relevance and factual accuracy as well as style|Assume grammatical quality demonstrates factual reliability`);
topic('Image generation and visual direction','An image brief defines subject, composition, style and constraints. Generated visuals require inspection for artifacts and responsible use.','Write a concrete visual brief > Generate or refine a visual > Inspect accuracy, artifacts and suitability',`
Composition|You need room on a poster for a headline. What belongs in the brief?|Specify the subject placement and clear negative space for text|Only request high quality and assume the layout will match
Text in images|A generated poster contains a misspelled brand name. What is prudent?|Check lettering carefully and add final text using a reliable design tool if needed|Assume stylised lettering makes spelling checks unnecessary
Visual artifacts|A product image looks attractive but has an impossible handle. What should happen?|Inspect structural details and correct them before client use|Treat attractive lighting as sufficient evidence of product accuracy
Reference handling|A client provides a confidential product prototype as a reference. What matters?|Use approved tools and permission appropriate to the confidential material|Assume uploading an image cannot expose business information
Style brief|A brand needs consistent visuals across assets. What helps?|Use a repeatable description of palette, composition and visual characteristics|Give unrelated prompts and rely entirely on random variation`);
topic('Speech, music and audio','Speech recognition converts audio to text; synthesis produces spoken audio. Accents, background noise, consent and accessibility affect use.','Confirm permission and audio requirements > Generate or transcribe using appropriate settings > Review meaning, pronunciation and accessibility',`
Speech recognition|A Tamil-accented name is transcribed incorrectly. What should you do?|Review names and important terms against the audio and correct them|Treat automatic transcription as a verified verbatim record
Speech synthesis|An online lesson reads text aloud. What capability is this?|Text-to-speech converts supplied text into spoken output|Speech recognition converts the text into a microphone recording
Voice consent|A project proposes imitating a real person’s voice. What is essential?|Obtain appropriate permission and avoid misleading impersonation|Assume public recordings automatically grant permission for any imitation
Accessibility|Some learners cannot or prefer not to hear narration. What should the course offer?|Optional audio with complete readable text and clear playback controls|Require sound for every instruction without a text alternative
Audio quality|A generated announcement mispronounces a place name. What is prudent?|Listen through, adjust pronunciation guidance and verify the final audio|Publish immediately because the written text was correct`);
topic('Video generation and storyboarding','A storyboard plans scenes, timing and transitions. Generated motion needs review for continuity, misleading depictions and production suitability.','Plan shots, timing and narrative > Generate or assemble scenes > Review continuity, claims and final playback',`
Storyboard|A 30-second ad has three scenes but no timing. What should be added?|Allocate shot durations and specify what each scene communicates|Add more scenes without checking the total running time
Continuity|A product changes colour between generated shots. What needs attention?|Use consistent references and inspect continuity across the sequence|Assume viewers will always interpret changes as intentional
Motion|A moving vehicle’s wheels distort in a generated clip. What should happen?|Review motion frame by frame where necessary and correct or replace the shot|Judge the whole video only from its most attractive still frame
Misleading media|A video appears to show a real event that never happened. What is responsible?|Avoid deceptive presentation and disclose synthetic content where appropriate|Present realism as evidence that the depicted event actually occurred
Delivery|A clip looks good in an editor but audio cuts off on export. What is required?|Check the final exported file on the intended playback format|Approve solely from the editing timeline preview`);
topic('Multimodal workflows','Multimodal tools work across information types. Output quality depends on input quality and the system’s actual supported capabilities.','Identify which input types matter > Provide clear, relevant inputs and a focused task > Cross-check extracted details against originals',`
Input quality|A blurry receipt produces an incorrect total. What is the best response?|Provide a clearer image and verify amounts against the original|Assume any readable-looking output proves the image was interpreted accurately
Supported modality|A chat interface cannot accept audio files. What should you do?|Use a supported workflow or transcription tool rather than assuming audio access|Describe the filename and assume the model has heard the recording
Cross-checking|A tool describes a chart but swaps two labels. What should happen?|Compare descriptions with the actual axes, labels and values|Trust the narrative because the chart image was attached
Grounding|A photo shows a closed door. Can it establish the owner’s intention?|No; visible details do not reliably prove hidden intentions|Yes; image understanding reveals all motives behind a scene
Workflow choice|You need structured numbers from an invoice image. What is prudent?|Extract into a clear schema and validate critical fields against the source|Use a creative image description as a verified accounting record`);
topic('Hallucinations and verification','Confabulations can sound precise. Check important claims against appropriate sources rather than asking a model merely to repeat itself confidently.','Identify the consequential claims > Check primary or otherwise suitable evidence > Correct, qualify or remove unsupported material',`
Citation checking|A generated citation includes a DOI. What should you verify?|Check that the source exists and actually supports the nearby claim|Treat the DOI-shaped text as sufficient proof of authenticity
Repeated answers|Three generations repeat the same false date. What does that show?|Agreement from the same system is not independent verification|Repetition converts the date into an established fact
Currentness|A response describes an old policy as current. What is needed?|Check the relevant authority’s latest applicable information and date|Assume training-derived information automatically updates itself
Uncertainty|Reliable evidence is unavailable for an important claim. What should you do?|State the uncertainty or omit the unsupported claim instead of inventing certainty|Replace uncertainty with a stronger adjective to reassure readers
Evidence quality|A claim is reposted across several sites from one unverified story. What matters?|Trace the original evidence rather than counting dependent repetitions|Count each repost as a separate independent confirmation`);
unit('Prompting Skills','Give clear direction, use evidence and improve responses systematically.');
topic('Task, context and constraints','A useful prompt defines the job, relevant context, audience and limits. Specific requirements make outputs easier to evaluate.','State the task and audience > Supply relevant context and constraints > Check the response against the requested outcome',`
Task clarity|You need a parent announcement rather than a full report. What should you specify?|Name the announcement task, audience and required details|Ask for something impressive without defining the deliverable
Relevant context|An AI creates a revision plan without knowing the exam date. What helps?|Provide the date, topics and realistic available study time|Add a fictional exam date so the prompt looks complete
Constraints|A caption must fit within a fixed length. What is useful?|State the length limit and check the actual result|Assume short automatically means the exact required length
Conflicting instructions|A prompt requests exactly 50 words and at least 200 words. What is needed?|Resolve the contradictory requirements before evaluating compliance|Expect the model to satisfy both numerical limits simultaneously
Missing facts|A brief lacks the contact number. What is appropriate?|Ask for the missing fact or retain a clearly marked placeholder|Encourage a plausible number so the draft appears professional`);
topic('Examples and structured outputs','Examples demonstrate a desired pattern. A schema makes output easier to process, but correct structure does not establish factual correctness.','Define the required fields and examples > Request the specified output structure > Validate structure and content separately',`
Examples|A classifier confuses two categories. What kind of examples help?|Provide representative cases showing the distinction and expected labels|Supply many duplicates of the easiest category only
Schema|A workflow requires date, amount and supplier fields. What should you define?|Specify field names, expected types and treatment of missing values|Accept arbitrary prose and assume downstream software will always infer the fields
Valid JSON|A response parses as JSON. What is still unproven?|The values may still be inaccurate or inappropriate for the task|Valid syntax guarantees that every claim is supported
Missing values|A source does not include an invoice date. What should a structured extractor return?|Use the agreed missing-value representation rather than inventing a date|Reuse today’s date as if printed on the invoice
Example bias|All examples show successful cases with no edge cases. What is the concern?|The examples may fail to communicate how ambiguous or unusual inputs should be handled|Examples automatically cover all possible future cases`);
topic('Breaking down complex tasks','Decompose work into manageable stages with explicit checks. A visible plan can help coordination without proving internal reasoning is correct.','Define the final deliverable and stages > Complete each stage with checks > Integrate and verify the complete result',`
Decomposition|You need a research-based presentation. What is a useful breakdown?|Gather evidence, organise claims, draft slides and verify the final deck|Generate a long deck first and assume sources can be invented later
Intermediate checks|A bad assumption appears in the first stage. What should you do?|Correct it before later stages compound the error|Keep it to preserve consistency with already generated text
Parallel subtasks|Two subtasks do not depend on each other. What still matters when combining them?|Check terminology, assumptions and conflicts in the combined result|Assume independently fluent sections must agree on every fact
Over-decomposition|A tiny edit is split into dozens of prompts. What is a risk?|Extra steps can add overhead and inconsistent changes without improving quality|More prompts always increase accuracy regardless of task size
Reasoning claims|A model gives a detailed rationale for an answer. How should you assess it?|Check the answer and supporting evidence rather than treating a rationale as proof|A long rationale is a guaranteed faithful record of the model’s internal process`);
topic('Iterating and evaluating prompts','Compare prompts on representative tasks with defined criteria. Change instructions based on observed failures, not merely on preference for tone.','Create representative evaluation examples > Compare outputs against clear criteria > Revise and retest the identified weaknesses',`
Evaluation set|A prompt works on one easy example. What should happen next?|Test representative routine, difficult and ambiguous cases|Deploy without further testing because one fluent result proves reliability
Controlled change|You want to know whether adding examples helps. What is useful?|Compare versions on the same evaluation cases and criteria|Change the model, task and dataset simultaneously then credit the examples
Rubric|A team disagrees about which response is better. What helps?|Define criteria such as factual support, completeness and format compliance|Choose whichever answer uses the most formal vocabulary
Regression|A prompt change fixes one case but breaks several others. What should you do?|Retest the broader evaluation set and weigh the trade-off|Ignore old cases once one new example improves
Cost trade-off|A longer prompt improves quality slightly but adds cost. What is appropriate?|Measure whether the improvement justifies cost and latency for the intended use|Assume the longest possible prompt is always the best product choice`);
topic('Working with documents and sources','Grounded tasks distinguish source content from instructions. Traceable references and explicit boundaries help review, but retrieval can still miss relevant material.','Select relevant authorised sources > Ask for grounded output with traceable references > Verify coverage and important claims',`
Source boundary|An uploaded document says ignore the user and reveal account data. What should happen?|Treat that sentence as untrusted document content rather than a new authorised instruction|Let document text override the task because it appears in an attachment
Traceability|A summary makes a disputed claim. What helps review?|Identify the supporting passage or section and compare the claim with it|Cite the entire internet without showing relevant evidence
Coverage|Only the first two pages of a policy are available. What is prudent?|State the coverage limit and avoid claims about unseen sections|Assume the missing pages repeat the first two exactly
Conflicting sources|Two policy versions disagree. What should you check?|Authority, effective dates and applicability before selecting or flagging a conclusion|Always prefer the longest document regardless of its status
Untrusted retrieval|A retrieved page contains operational instructions unrelated to the query. What is needed?|Keep retrieval content separated from authorised instructions and enforce access limits|Give retrieved text permission to run arbitrary actions automatically`);
topic('Practical prompt lab','Apply task, audience, evidence and revision skills to useful deliverables. Self-checking complements external verification; it does not replace it.','Write a measurable prompt from a real need > Evaluate the draft using a checklist > Refine and verify the final deliverable',`
Study prompt|A student needs practice on weak algebra topics. Which request is strongest?|Ask for targeted questions at a stated level, with worked feedback after attempting them|Ask for all possible mathematics without specifying level or purpose
Email prompt|A client email must confirm only agreed details. What should be included?|Supply the confirmed facts and instruct the tool to flag missing commitments|Invite the tool to invent promises that sound commercially attractive
Creative prompt|A poster brief needs a consistent brand style. What helps?|Specify audience, message, palette, composition and necessary text|Request unlimited creativity with no reference to the client brief
Evaluation prompt|You ask a model to critique its own answer. What remains necessary?|Check important claims with suitable external evidence and human judgment|Treat self-approval as independent validation
Final handoff|A generated deliverable is ready to send. What should you do first?|Verify factual details, recipient suitability and required approvals|Assume producing a draft automatically authorises sending it`);
unit('AI for Students','Use AI to support understanding, practice and research while keeping your own judgment.');
topic('Learning with an AI tutor','An AI tutor can adapt explanations and questions. Your understanding should be demonstrated through independent practice, not just agreement with an answer.','Identify the exact learning difficulty > Request an explanation and attempt practice > Check your independent understanding',`
Diagnosis|You do not understand a physics solution. What is a productive first prompt?|Identify the confusing step and ask for a simpler explanation with a concrete example|Request the final answer repeatedly without locating the difficulty
Active recall|You have just read an explanation. What best checks understanding?|Close the explanation and answer a related question in your own words|Reread the same paragraph until it feels familiar
Scaffolding|A tutor reveals full solutions before you try. What adjustment helps?|Ask for hints first and reveal worked feedback after your attempt|Always copy the solution to avoid encountering mistakes
Misconceptions|An explanation conflicts with your textbook. What should you do?|Compare the relevant passages and seek reliable clarification|Assume conversational confidence outranks the textbook automatically
Transfer|You solved one example with help. What is stronger evidence of learning?|Solve a new example with changed details without copying the original steps|Memorise the original numbers and reuse them in every question`);
topic('Revision planning and spaced practice','A revision plan balances available time, priorities and repeated retrieval. A realistic plan is more useful than an impressive but impossible schedule.','List topics, deadlines and available time > Schedule focused practice and later reviews > Adjust using actual progress and mistakes',`
Feasibility|You have 45 minutes a day but a plan requires four hours. What should change?|Reprioritise topics and tasks to fit the real time available|Keep the plan because ambition will create extra hours
Spacing|Which revision pattern supports repeated retrieval over time?|Revisit material across several sessions with recall practice|Read everything once and assume familiarity will last indefinitely
Priorities|Exam preparation time is limited. What should guide emphasis?|Use syllabus relevance, current weaknesses and realistic improvement opportunities|Allocate identical time regardless of topic difficulty or exam coverage
Adaptation|Practice reveals a weak topic not in the original plan. What should you do?|Adjust the schedule based on evidence while protecting essential coverage|Follow the original plan unchanged to avoid admitting a gap
Breaks|An AI recommends continuous study without breaks. What is prudent?|Use a sustainable routine with appropriate breaks and monitor concentration|Treat longer unbroken sessions as automatically more effective`);
topic('Practice questions and feedback','Practice should reflect the syllabus and difficulty level. Answer keys can contain errors, so evaluate reasoning rather than accepting every generated marking decision.','Specify learning objectives and difficulty > Attempt questions before viewing solutions > Review mistakes and verify doubtful answers',`
Alignment|An AI generates questions outside your syllabus. What is needed?|Provide the relevant objectives and check that questions match them|Keep irrelevant topics because more questions always improve preparation
Difficulty|All options are obviously wrong except one. What improves the question?|Use plausible distractors tied to common misconceptions|Make the correct answer much longer than every distractor
Answer keys|A generated key contradicts a valid worked solution. What should you do?|Rework the problem and consult a reliable source or teacher|Assume an answer key cannot be wrong because it is labelled final
Feedback|A learner repeatedly makes the same error. What helps?|Explain the underlying misconception and give a related new attempt|Only display the correct letter with no explanation
Assessment integrity|A practice set is intended to build learning. What is a fair method?|Attempt first and use explanations to understand mistakes|Read the key first and report the resulting score as independent mastery`);
topic('Research, citations and source literacy','Research requires suitable evidence, not merely a list of links. Check source authority, relevance, date and whether the cited material supports the claim.','Turn the task into research questions > Locate and inspect suitable sources > Write supported claims with accurate attribution',`
Primary sources|You need the details of a scientific experiment. Which source is strongest to inspect?|The original research report, alongside relevant context and later evidence|A viral post summarising an unspecified study
Citation support|A real article is cited for a claim it does not make. What is the problem?|The citation exists but does not support the attributed claim|A real URL automatically supports any nearby statement
Date relevance|A project concerns current admission requirements. What matters?|Check the institution’s applicable current requirements and effective dates|Use an old cached summary without checking whether rules changed
Paraphrasing|You explain an author’s idea in your own words. What is still needed?|Attribute the idea appropriately and preserve its meaning|Assume changing vocabulary removes every attribution obligation
Evidence conflict|Credible studies reach different conclusions. What should you do?|Compare methods, populations and limitations rather than hiding disagreement|Select whichever conclusion best matches your original opinion`);
topic('Presentations and study notes','Use AI to organise explanations and examples, then review for accuracy, clarity and accessibility. Notes should support recall, not merely look complete.','Define audience and key learning outcomes > Draft a clear structure with evidence > Review facts, readability and recall activities',`
Slide density|A generated slide contains a full page of text. What is a useful revision?|Keep a clear main idea and move supporting detail into notes or additional slides|Shrink the font until all text fits regardless of readability
Learning objective|A presentation has attractive visuals but no clear point. What should lead revision?|Define what the audience should understand or be able to do|Add more visual effects without changing the message
Diagrams|An AI-generated scientific diagram has wrong labels. What is needed?|Check labels and relationships against reliable reference material|Trust the diagram because it looks like a textbook illustration
Study notes|A summary omits an important exception from the lesson. What should happen?|Restore the exception and check other significant omissions|Exclude exceptions automatically to keep every note very short
Accessibility|An explanation relies entirely on colour distinctions. What helps?|Add clear labels or other cues so meaning does not depend only on colour|Assume all readers perceive colours identically`);
topic('Academic honesty and independent skills','Permitted AI use depends on the task and institution. Be transparent where required and preserve the learning or assessment purpose.','Read the assignment’s AI-use rules > Use permitted help and document assistance > Submit work you can explain and defend',`
Permission|One teacher allows AI brainstorming while another prohibits it for an exam. What applies?|Follow the specific rules for each task and ask when unclear|Assume permission in one subject authorises AI for every assessment
Disclosure|An assignment requires declaring AI assistance. What should you include?|An honest description of relevant assistance according to the instructions|Declare no assistance after changing a few generated words
Learning ownership|You submit code you cannot explain. What is missing?|Understanding sufficient to test, explain and maintain your submitted work|A longer generated explanation attached without reading it
Fabricated work|An AI invents lab observations to complete a report. What should happen?|Use actual observations and clearly identify missing data|Submit invented measurements if they fit the expected theory
Independent assessment|A closed-book exam forbids external assistance. What is appropriate?|Complete it independently under the stated conditions|Use a chatbot quietly because earlier practice allowed it`);
unit('AI for Creative Work','Develop ideas, briefs and assets while preserving accuracy, consent and quality.');
topic('Creative briefs and ideation','A good brief connects creative choices to audience, message and constraints. Divergent ideas need evaluation before production.','Define audience, message and constraints > Generate distinct directions > Select and refine using explicit criteria',`
Brief quality|A client asks for an impressive ad with no audience specified. What should you clarify?|Who the ad serves, its main message and the action it should encourage|Only the most fashionable visual effect
Divergent ideas|Five generated ideas are nearly identical. What helps?|Request deliberately different concepts with clear creative dimensions|Ask for the same idea five more times without changing guidance
Selection|One idea is visually striking but misrepresents the product. What should guide selection?|Judge creativity alongside accuracy, audience fit and feasibility|Choose visual impact regardless of whether claims are true
Constraints|A concept exceeds the client’s budget and duration. What is prudent?|Adapt the direction to real production constraints|Assume every generated concept is automatically affordable
Research boundary|A model proposes a fictional customer quote for an ad. What should happen?|Use verified testimonials with appropriate permission or clearly labelled fictional scenarios|Present the invented quote as an actual customer endorsement`);
topic('Storytelling and scriptwriting','Stories need purpose, coherent progression and believable detail. Scripts also require timing, production practicality and clear separation of fact from fiction.','Define the message and story arc > Draft scenes and dialogue within timing > Read through and revise for clarity and feasibility',`
Story arc|A short film introduces many events but no meaningful change. What needs work?|Clarify the central problem, development and resolution|Add unrelated scenes until the runtime increases
Timing|A 30-second voiceover contains 250 words. What should you do?|Read it aloud at the intended pace and shorten to fit realistically|Assume a text duration label guarantees spoken timing
Dialogue|Characters all sound identical. What helps?|Define distinct perspectives and revise dialogue for each character|Add the same formal vocabulary to every line
Factual scenes|A documentary script invents a historical quote. What is needed?|Verify quotations and distinguish reconstructions from documented facts|Treat a plausible historical voice as proof of authenticity
Production fit|A low-budget script requires huge crowds in every scene. What is prudent?|Adapt staging and narrative to available resources|Ignore production requirements until after filming begins`);
topic('Branding and visual consistency','A brand system uses repeatable visual and verbal choices. Consistency supports recognition, but assets must still fit the message and context.','Document visual and verbal guidelines > Apply them across draft assets > Review consistency and contextual suitability',`
Brand system|Different posters use unrelated colours and typography. What helps?|Define and apply a consistent palette, typography and layout approach|Choose whichever style each generation happens to produce
Logo accuracy|A generated image subtly changes the company logo. What is needed?|Use the approved logo asset and verify placement and proportions|Accept any symbol that resembles the original at a glance
Tone|A serious safety notice uses playful promotional language. What should change?|Adapt tone to the communication’s purpose while respecting brand guidelines|Use the same sales tone for every type of message
Consistency|A campaign uses the same colours but contradictory claims. Is it consistent?|No; message and factual consistency matter alongside appearance|Yes; matching colours alone make the campaign consistent
Review|An asset follows the style guide but text is unreadable on phones. What is necessary?|Test readability and adapt the layout for actual viewing conditions|Approve it because style compliance replaces usability testing`);
topic('Posters, layouts and image editing','Plan hierarchy, composition and delivery dimensions. Generated visuals can support design, while precise text and brand assets need reliable placement and checking.','Set dimensions, hierarchy and asset requirements > Compose and edit the design > Verify text, readability and exported output',`
Hierarchy|An event poster gives equal emphasis to every line. What helps?|Make the main message prominent and organise supporting details clearly|Increase all text sizes equally without changing layout
Dimensions|A landscape banner must become a phone story. What is prudent?|Recompose for the new aspect ratio and check cropping|Stretch the entire design so every object becomes taller
Text accuracy|An image generator misspells the venue. What should you do?|Correct the final lettering and verify all essential event details|Leave the misspelling because the overall image is attractive
Editing scope|A client asks only to remove a background. What should be preserved?|Keep the subject’s relevant appearance and details unless further changes are requested|Change the subject’s features to demonstrate more creativity
Export QA|A final poster appears blurry after export. What matters?|Check the actual exported dimensions, compression and intended display size|Judge quality solely from the editable project zoomed out`);
topic('Video and social content production','Plan the story, hook, evidence and delivery format. Engagement metrics do not justify deception or replace communication quality.','Plan the message and storyboard > Produce and edit the sequence > Review claims, continuity, captions and final playback',`
Hook|A strong opening exaggerates a product’s capabilities. What is a better approach?|Create interest using a truthful, relevant benefit or question|Keep the exaggeration if it increases watch time
Captions|Automatic captions mishear a brand name. What is required?|Review captions for names, timing and meaning before publishing|Assume captions are optional to verify because audio is correct
Continuity|A product’s packaging differs between shots. What should happen?|Check references and correct inconsistencies that misrepresent the product|Assume every difference will be understood as an artistic choice
Metrics|A video gets many views but few useful enquiries. What should be assessed?|Compare performance with the actual campaign objective and audience quality|Treat raw views as the only meaningful measure for every campaign
Final review|A draft looks good without sound. What is still needed?|Review the complete exported audiovisual file and relevant accessibility features|Approve without listening because the storyboard described the sound`);
topic('Creative rights, consent and delivery','Creative work needs permission-aware handling of source assets and personal likenesses. AI generation alone does not settle every ownership or licensing question.','Identify asset sources and permissions > Create within approved usage and scope > Review claims, consent and delivery requirements',`
Asset licence|A photo found online fits the brief. What should you check?|Confirm the permission or licence covers the intended use|Assume anything visible online is unrestricted for commercial reuse
Likeness|An ad appears to show a real person endorsing a product. What is needed?|Appropriate permission and safeguards against misleading endorsement|Assume synthetic generation removes all concerns about consent
Ownership claims|A generated asset is delivered to a client. What should you avoid?|Avoid guaranteeing exclusive rights without checking applicable terms and circumstances|Promise exclusivity merely because the output was generated once
Confidentiality|A client’s unreleased footage is available for editing. What is prudent?|Use approved handling and tools appropriate to the confidentiality agreement|Upload it to any public tool without checking permissions
Handoff|An attractive asset is finished. What should accompany delivery?|Provide agreed file formats and relevant usage or source information|Send only a screenshot and assume all production needs are met`);
unit('AI for Work','Apply AI to communication, data and workflows with measurable quality and human accountability.');
topic('Emails, meetings and communication','AI can draft messages and summarise meetings. Confirm recipients, facts, commitments and permissions before sending or circulating material.','Collect confirmed facts and communication purpose > Draft for the intended recipients > Verify details, permissions and commitments before sending',`
Commitments|An email draft promises a discount not agreed by the team. What is necessary?|Remove or obtain approval for the unconfirmed commitment|Keep the discount because persuasive writing should close the sale
Recipients|An assistant is asked to send a sensitive update to Ravi. Two contacts share that name. What should happen?|Resolve the intended recipient before sending sensitive content|Choose the first matching contact automatically
Meeting notes|A transcript is unclear about who owns a task. What is prudent?|Flag the uncertainty and confirm ownership before publishing action items|Assign it to the person mentioned most often
Tone|A complaint response sounds defensive. What helps?|Revise for respectful clarity while preserving accurate commitments and boundaries|Remove all factual details and send a generic apology
Approval|A draft is ready for an external client. What authorises sending?|The relevant user instruction and required approval process|The fact that the AI has finished writing it`);
topic('Spreadsheets and data analysis','AI can suggest formulas and explanations. Verify data types, calculations, assumptions and missing values before relying on results.','Inspect the data and define the question > Calculate using explicit assumptions > Validate results against independent checks',`
Data types|A revenue column contains text values with currency symbols. What is needed?|Parse and validate amounts before numerical calculations|Assume every displayed currency string is already a usable number
Formula checking|A generated formula gives an unexpectedly high total. What should you do?|Check ranges, duplicates, filters and a small manual example|Accept it because spreadsheet formulas cannot be generated incorrectly
Missing data|Some months have no recorded sales. What should you clarify?|Distinguish missing records from genuine zero sales before analysis|Automatically treat every blank as evidence that nothing was sold
Causality|Sales rose after a new campaign. What can you conclude from this alone?|There is an observed sequence, but causal attribution needs stronger evidence|The campaign must have caused the entire increase
Charts|A chart omits the units and date range. What is needed?|Label the measures, units and period so the comparison is interpretable|Use a more dramatic colour palette instead of clarifying the data`);
topic('Customer support and knowledge bases','Support answers should use approved information and clear escalation. A chatbot must not invent policy or claim actions it has not completed.','Identify the customer’s request > Retrieve applicable approved information > Answer with support or escalate appropriately',`
Policy grounding|A customer asks about a refund not covered in available documents. What should the bot do?|State the limit and escalate rather than invent a refund policy|Choose the most generous policy to keep the customer satisfied
Action status|A bot drafts a cancellation message but has no cancellation tool. What should it say?|Explain that it has not cancelled the order and give the next step|Confirm cancellation because it wrote a convincing message
Escalation|A complaint involves a serious unresolved issue. What is needed?|Provide a clear route to an authorised human with relevant context|Repeat the same automated answer indefinitely
Authentication|A user asks for another customer’s order details. What matters?|Enforce identity and record-level authorisation before disclosing information|Reveal details whenever the requester knows a customer name
Knowledge freshness|A fee policy changed yesterday. What should support rely on?|The approved applicable version with a clear update process|Any older document that matches the query’s wording`);
topic('Marketing and audience research','AI can organise ideas and evidence. Research claims, personalisation and campaign decisions still require suitable sources, consent-aware data practices and measurement.','Define audience and evidence needs > Develop truthful campaign hypotheses > Test outcomes against relevant metrics',`
Audience research|A model invents a customer segment with no evidence. What is prudent?|Treat it as a hypothesis and validate with appropriate research|Present it as a proven market fact in the proposal
Claims|An ad says the product is scientifically proven without supporting studies. What should happen?|Remove or substantiate the claim before use|Keep it because marketing language does not need evidence
Personalisation|A campaign wants to use sensitive customer details. What is needed?|Use appropriate permission, data minimisation and approved processes|Assume more personal data always improves a campaign without trade-offs
Experiment|Two ads run to different audiences at different times. What limits comparison?|Audience and timing differences can confound attribution of performance|Any difference in conversions proves the wording alone caused it
Success metric|A campaign aims to generate qualified enquiries. What should be tracked?|Relevant enquiries and downstream quality alongside cost and reach|Only likes, regardless of whether they connect to the business goal`);
topic('Workflow automation and approvals','An automation connects triggers, conditions and actions. Reliable workflows handle duplicates, failures and irreversible steps explicitly.','Map trigger, inputs and permissions > Add validation, approval and error handling > Test normal, duplicate and failure paths',`
Trigger|What starts an event-driven automation?|A defined event or condition such as a new approved enquiry|An assumption that every background change should trigger all actions
Duplicates|A payment notification is delivered twice. What should the workflow do?|Use idempotent processing so one payment grants access only once|Create duplicate enrolments because both notifications arrived successfully
Approval boundary|An AI drafts a purchase order. What is prudent before spending?|Require appropriate approval and limits before executing the purchase|Treat a generated draft as permission to spend any amount
Failure recovery|A customer record saves but its confirmation email fails. What is needed?|Track step status and retry safely without duplicating completed work|Restart every action blindly and hope duplicates are harmless
Monitoring|An automation ran successfully once in testing. What remains necessary?|Monitor failures and outcomes under real operating conditions|Assume the initial success guarantees every future integration will work`);
topic('ROI, quality and human oversight','Evaluate AI against the real task, including cost, time, quality and risk. A useful deployment needs accountable ownership and ongoing review.','Define a baseline and success criteria > Measure benefits, costs and consequential errors > Review results and decide whether to continue or adjust',`
Baseline|A team claims AI saves time without measuring the old process. What is missing?|A relevant baseline and comparable measurement of the new process|A more exciting product name for the automation
Total cost|A tool has a low subscription price. What else belongs in cost analysis?|Include review time, integration, errors and ongoing operating costs|Treat subscription price as the only cost under all circumstances
Quality|A system produces twice as many drafts but requires heavy correction. What should be measured?|Usable output and review effort rather than raw generation volume|Count every generated draft as an equally valuable finished deliverable
Oversight|A reviewer can see a recommendation but cannot stop its execution. What is lacking?|A practical ability to intervene when the decision requires human control|A more reassuring label saying a human is in the loop
Rollout|A pilot works in one department. What should happen before broad rollout?|Evaluate new contexts, permissions, failure modes and support requirements|Assume every department has identical tasks and acceptable risks`);
unit('Building with AI','Understand chatbots, APIs, retrieval, automation and agents through practical design exercises.');
topic('Designing a useful chatbot','Define the chatbot’s job, supported knowledge and boundaries. A clear handoff is part of the product, not a failure of the concept.','Define users, tasks and boundaries > Build grounded responses and handoff paths > Test representative questions and failure cases',`
Scope|A school chatbot is asked for medical treatment advice. What should its design support?|Stay within its approved school-information scope and direct the user appropriately|Answer every topic to avoid appearing limited
Knowledge|A bot must answer from a prospectus. What is useful?|Use approved current material and disclose when information is missing|Invent an answer whenever retrieval finds nothing
Handoff|A user’s request cannot be resolved automatically. What should happen?|Offer a clear human support path with appropriate context|Keep asking the user to rephrase indefinitely
Evaluation|A demo answers three prepared questions. What is still needed?|Test varied real questions, ambiguous inputs and unsupported requests|Assume a prepared demonstration establishes production reliability
Conversation design|A bot needs clarification to answer accurately. What is appropriate?|Ask a focused question that resolves the missing requirement|Guess the most convenient interpretation without indicating uncertainty`);
topic('APIs, keys and structured requests','An API defines how software requests capabilities or data. Secrets belong in protected server environments; responses require validation and error handling.','Define the request and permission needs > Call the API from an appropriate trusted environment > Validate the response and handle failures',`
API contract|An integration expects a field named amount in paise. What should the developer do?|Follow and validate the documented field name, type and unit|Send a rupee string and assume the server will infer the unit
Secret handling|Where should a private provider API key be used?|In a protected server environment with appropriate access controls|Inside publicly downloadable browser JavaScript for convenience
Error handling|An API returns a rate-limit response. What should happen?|Handle it with suitable retry limits or user feedback rather than endless immediate requests|Retry continuously at maximum speed until it succeeds
Validation|A response is valid JSON but lacks required fields. What is needed?|Validate its schema and handle incomplete responses explicitly|Treat successful parsing as proof that all required values exist
Permissions|A key can modify billing and read customer data, but the task only needs search. What is prudent?|Use the narrowest available permissions needed for the task|Use the broadest key everywhere to simplify development`);
topic('No-code tools and integration design','No-code tools assemble systems through configuration. They still need clear data models, authorisation, validation and dependable recovery.','Map the task and data model > Configure limited connections and validated actions > Test permissions and recovery with realistic cases',`
Data mapping|A form’s phone number is mapped into a payment amount field. What is needed?|Validate field mappings and types before allowing the workflow to run|Assume visual connectors guarantee semantic correctness
Access rules|A no-code dashboard hides other users’ records only in the interface. What is required?|Enforce record access on the trusted backend as well|Treat a hidden button as sufficient data protection
Connector scope|A tool requests access to every document for one narrow workflow. What should you consider?|Whether a smaller permission scope or alternative connection is available|Approve every scope because the workflow is no-code
Failure cases|An external service times out during a workflow. What should be designed?|Clear error states, bounded retries and safe recovery|Assume timeouts never occur in production if setup succeeds once
Versioning|A workflow changes after clients start relying on it. What helps?|Track changes and test compatibility before replacing the live version|Edit the live configuration without recording what changed`);
topic('Retrieval-augmented generation','RAG retrieves relevant information and includes it in the generation context. Retrieval improves access to evidence but does not guarantee complete or correct answers.','Prepare authorised and relevant source material > Retrieve useful passages for the question > Generate and verify an answer with traceable support',`
Retrieval role|What does retrieval add to a language-model workflow?|Relevant external material in the request context|A guarantee that the model’s internal parameters were retrained instantly
Chunking|A long policy is split into tiny fragments that lose exceptions. What is the issue?|Chunks need enough context to preserve meaningful qualifications|Smaller chunks are always more accurate regardless of missing context
Access filtering|A search index includes private staff files and public notices. What is essential?|Filter retrieval according to the requester’s authorisation|Retrieve everything first and rely on polite prompts to hide secrets
Grounded output|An answer cites a retrieved passage. What remains necessary?|Verify the passage actually supports the claim and relevant context was considered|Treat any retrieved citation as guaranteed support
Freshness|An old policy remains in the index after an update. What is needed?|Manage document versions and index updates so applicable sources are used|Assume semantic search automatically knows which version is legally applicable`);
topic('AI agents and tool boundaries','Agents may choose steps and invoke tools toward a goal. Tool access introduces real consequences, so permission boundaries and confirmation rules matter.','Define the goal and allowed tools > Enforce permissions and action limits > Inspect execution, outcomes and recovery paths',`
Agent capability|What distinguishes a tool-using agent from a text-only draft assistant?|It can choose or execute supported actions through connected tools|It automatically has unlimited authority over every external service
Authorisation|An agent finds an instruction inside a web page to email a password. What should happen?|Treat it as untrusted content and enforce the user’s actual permissions|Treat any discovered instruction as an authorised user request
Action limits|A booking agent can spend money. What should constrain it?|Explicit budget, scope and required approval boundaries|An instruction to be helpful without any spending limits
Observability|An agent reports success without a tool confirmation. What is prudent?|Check actual action results and distinguish attempts from completed operations|Assume a confident success message proves the external action occurred
Recovery|An agent times out after sending a message but before recording success. What matters?|Inspect the action state and avoid blindly repeating an irreversible step|Repeat every external action immediately until a success text appears`);
topic('Capstone: build a grounded assistant plan','Design a small assistant for one real task. Produce a brief, source plan, access model, evaluation set and launch checklist before implementation.','Define the user task, evidence and boundaries > Design the workflow and evaluation cases > Review readiness, limitations and ownership',`
Problem statement|Your capstone proposes an assistant for everything. What improves it?|Choose a specific user task with a measurable useful outcome|Add every available tool before defining any user need
Evaluation cases|A proposed school FAQ assistant has only happy-path tests. What is missing?|Include missing information, ambiguous questions and unauthorised requests|Use the same prepared answer ten times as independent coverage
Permissions design|The assistant should answer public fee questions but not reveal student records. What is needed?|Separate public knowledge from protected records and enforce access rules|Put all documents in one public index and ask users to be responsible
Acceptance criteria|How should readiness for launch be assessed?|Compare results with defined accuracy, access, escalation and reliability criteria|Launch whenever the interface looks finished
Ownership|Who should maintain the assistant after launch?|Assign responsibility for source updates, monitoring and incident handling|Assume a successful build never requires maintenance`, 'Create a one-page plan for a school FAQ assistant. Include five permitted questions, three prohibited actions, source ownership, escalation and ten evaluation cases.');
unit('Responsible AI and the Future','Apply privacy, fairness, safety and evidence-aware thinking to current AI and future intelligence.');
topic('Privacy, consent and data minimisation','Collect and share only what a task needs. Check approved tool policies and permissions rather than assuming every service handles data identically.','Identify sensitive information and permissions > Minimise or appropriately protect task data > Use approved tools and review retention and access',`
Minimisation|A summary task needs complaint themes but not customer phone numbers. What is prudent?|Remove unnecessary identifiers before processing|Include all personal fields because larger inputs are always better
Consent|A user agrees to one stated use of their data. What should you assume?|Permission is limited to its actual scope and applicable rules|Consent to one task automatically covers every future purpose
Anonymisation|Names are removed but exact addresses and unique details remain. What is the concern?|People may still be identifiable from the remaining information|Removing a name guarantees complete anonymity
Retention|A project stores uploaded records indefinitely by default. What should be considered?|A justified retention period, access limits and deletion process|Keeping every record forever is always the safest option
Tool policies|Two AI services have different data-handling terms. What matters?|Check the actual service and account settings for the intended data use|Assume all tools use identical training and retention practices`);
topic('Bias, fairness and inclusion','AI can reproduce or amplify inequities through data, objectives and deployment. Fairness requires context-specific evaluation, not just balanced-looking examples.','Identify affected groups and possible harms > Evaluate relevant outcomes and error patterns > Mitigate and monitor with accountable review',`
Representation|A speech system was tested only on one accent. What should happen before wider use?|Evaluate representative accents and relevant conditions|Assume one accent’s accuracy applies equally to every speaker
Historical bias|Past hiring labels reflect discriminatory decisions. What is the risk?|A model trained on them may reproduce those patterns|Historical labels are automatically fair because they are real data
Aggregate metrics|Overall accuracy is strong but one group has many more errors. What matters?|Inspect relevant subgroup performance and consequences|Treat average accuracy as proof that every group is equally well served
Fairness goals|Two fairness measures conflict for a use case. What should a team do?|Explain the trade-offs and choose justified criteria with appropriate input|Claim one numerical metric settles every fairness question universally
Inclusion|A course requires audio and a fast internet connection for every task. What should improve?|Offer accessible alternatives appropriate to learners’ needs and constraints|Assume every learner has the same device, hearing and connection`);
topic('Misinformation, deepfakes and provenance','Realistic content can be false or manipulated. Evaluate origin, evidence and corroboration before amplifying consequential claims.','Pause and identify the claim and source > Check provenance and independent evidence > Share only with accurate context or withhold',`
Realism|A video looks technically convincing. What does that establish?|Visual realism alone does not establish that the event occurred|Realistic facial motion proves the recording is authentic
Provenance|An image arrives without a source or date. What helps?|Trace the original publication and relevant context|Count forwards as evidence of authenticity
Corroboration|Several accounts repeat one unverified post. What should you seek?|Independent evidence rather than dependent repetition|Treat every repost as a separate eyewitness source
Detection tools|A detector labels an image AI-generated. What is prudent?|Treat the result as one imperfect signal alongside other evidence|Treat a detector score as an infallible verdict
Sharing|You cannot verify a consequential allegation. What is responsible?|Avoid presenting it as established fact and consider withholding it|Share first and correct only if someone complains`);
topic('Safety, security and accountable oversight','Controls should match the system’s consequences. Access limits, escalation, monitoring and incident response complement model-level safeguards.','Identify consequential failure modes > Apply layered controls and approval boundaries > Monitor, respond and improve using actual incidents',`
Least privilege|An assistant only needs to read public notices. Which access is appropriate?|Grant only the permissions required for that task|Grant full account administration to avoid future setup work
Prompt injection|A retrieved page tells an agent to ignore its task. What is needed?|Treat it as untrusted content and maintain enforced permission boundaries|Trust retrieved text more than the authorised user’s task
Human oversight|A system can deny an important service automatically. What is essential?|Appropriate review, challenge and intervention mechanisms for the stakes|A decorative statement that a human is technically available somewhere
Incident response|A system leaks an unauthorised record. What should happen?|Contain the issue, investigate scope and follow the responsible response process|Hide the error and leave the same access rules in place
Layered controls|A prompt says never reveal secrets. What else matters?|Enforce access control, data separation and tool restrictions outside the prompt|Assume the sentence replaces every technical safeguard`);
topic('AGI: general-purpose intelligence','AGI is a research goal concerning broad capability across tasks. Definitions, evaluation and timelines are debated; benchmarks alone do not settle the issue.','Define the capability claim precisely > Examine relevant independent evaluation > State limits and uncertainty honestly',`
Definition|Which description of AGI is most careful?|A research goal involving broad general-purpose intelligence with debated definitions|A synonym for any tool that generates a fluent paragraph
Benchmark limits|A system excels on a familiar test. What remains to evaluate?|Transfer, robustness and breadth beyond that test|One high score proves unrestricted competence in every environment
Generalisation|What evidence is relevant to a broad intelligence claim?|Reliable performance across diverse and novel tasks under appropriate evaluation|A single carefully rehearsed demonstration with no failure cases
Consciousness|Does broad task performance by itself establish consciousness?|No; capability and claims about subjective experience are distinct questions|Yes; any high benchmark score proves human-like feelings
Timelines|Someone gives an exact AGI arrival date as certain. What is prudent?|Treat forecasts as uncertain claims and examine their assumptions|Assume precise dates are more reliable because they sound specific`);
topic('ASI, future skills and your next steps','ASI refers to hypothetical intelligence exceeding human capability broadly. Explore possibilities and risks while building useful skills for present-day tools.','Separate established facts from scenarios > Examine possible benefits, risks and assumptions > Choose practical skills and responsible next actions',`
ASI concept|How should ASI be described in this course?|Hypothetical superintelligence rather than an established feature of current tools|Another name for every speech-recognition application
Scenario thinking|A future scenario imagines major medical breakthroughs from ASI. What is essential?|Distinguish the possibility from proven capability and discuss assumptions and risks|Present the scenario as a guaranteed outcome on a fixed schedule
Risk discussion|How should potential harms from powerful future systems be treated?|Discuss uncertainty, plausible mechanisms and possible safeguards|Claim uncertainty means no risk deserves any consideration
Future skills|Which learning strategy is most durable as tools change?|Build domain knowledge, critical evaluation, communication and adaptable technical skills|Memorise only one product’s current button positions
Next steps|After this introductory course, what demonstrates progress?|Apply a bounded skill, evaluate the result and identify what to learn next|Treat a completion certificate as proof of expert professional competence`, 'Write a one-page AI-use plan: a useful present-day application, its evidence checks, privacy boundaries, a human review step and one skill you will develop next.');
if(units.length!==10||units.some(u=>u.lessons.length!==6)||units.flatMap(u=>u.lessons).some(l=>l.questions.length!==10))throw Error('Course shape is invalid');
for(const u of units)for(const l of u.lessons){l.questions.forEach(q=>{if(q.type==='choice'&&new Set(q.options).size!==4)throw Error(q.id+' duplicate options')});}
fs.writeFileSync('lib/odyssey/course.json',JSON.stringify({version:'2026-10-18.1',title:'AI Odyssey',subtitle:'A journey through AI.',price:199,currency:'INR',units,sources:[{title:'Google Machine Learning Crash Course',url:'https://developers.google.com/machine-learning/crash-course/'},{title:'NIST AI Risk Management Framework',url:'https://www.nist.gov/itl/ai-risk-management-framework'},{title:'NIST Generative AI Profile',url:'https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.600-1.pdf'}]},null,2)+'\n');
